    # --- по четыре на каждый повод ------------------------------------------------
    # Библиотека росла там, где на неё смотрели: «человек рядом» — девяносто
    # сценок, «зовёт внимание» — пятнадцать. А сорок один повод был отыгран
    # одной-двумя, и это значило буквально следующее: таймер звонит — персонаж
    # ВСЕГДА делает «дзинь»; сказали «спасибо» — ВСЕГДА тот же поклон;
    # понедельник — ВСЕГДА одна и та же реплика. Редкий повод тем и заметен,
    # что его ждёшь, и один-единственный отклик выдаёт механизм вернее, чем
    # сотня одинаковых сценок в покое: там взгляд скользит, здесь — упирается.
    #
    # Четыре — не круглое число из головы: при трёх любой повтор читается
    # через раз, при четырёх с привыканием (вес падает после игры) подряд
    # одинаковое почти не выпадает. Ниже — добор до четырёх по всем поводам,
