    # --- жесты речи: их видно чаще всего, а было их четыре ------------------------
    # «Говорит» — не событие на секунду, а фон на всю реплику: сценки идут
    # кругами, пока не замолчит. И это ровно те секунды, когда на персонажа
    # смотрят в упор. Четырёх жестов хватало на четыре круга — дальше человек
    # видел кивок, бровь, взмах, взгляд, кивок, бровь, взмах, взгляд. Прибор
    # так и сказал: четыре самые частые сценки за сутки — все четыре «говорит»,
    # каждая по 5% всего, что персонаж вообще делает при человеке.
    #
    # Рот ни одна из них не трогает: губами управляет липсинк (face/lips.py),
    # и сценка, закрывшая рот посреди слова, читается как поломка.
